SELECT p.person_id, p.name, p.id_number, p.gender, p.ethnicity, p.birth_date, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) AS age, h.detailed_address FROM ads_person_basic_info p INNER JOIN ads_residence_relation rr ON p.person_id = rr.person_id AND rr.delete_flag = 0 INNER JOIN ads_house_basic_info h ON rr.house_id = h.house_id AND h.delete_flag = 0 WHERE p.delete_flag = 0 AND h.dept_id = '310110018012' AND p.birth_date IS NOT NULL AND TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) >= 100 ORDER BY age DESC limit 10;
